using HeroDefense.Build;using HeroDefense.Battle.Combat;using HeroDefense.Battle.Projectiles;using HeroDefense.Battle.Effects;using UnityEngine;using UnityEngine.UI;
namespace HeroDefense.Performance
{
    public static class RuntimeQualityService{public static int RecommendedPlayerLimit=>HeroDefense.Save.SaveGameManager.Instance?.Data.settings.graphicsQuality==HeroDefense.Save.GraphicsQualityOption.Low?24:36;public static int RecommendedEnemyLimit=>HeroDefense.Save.SaveGameManager.Instance?.Data.settings.graphicsQuality==HeroDefense.Save.GraphicsQualityOption.Low?28:40;}
    public sealed class PerformanceMonitor:MonoBehaviour
    {public static PerformanceMonitor Instance{get;private set;}private Text label;private GameObject persistentCanvas;private float elapsed;private int frames;private void Awake(){if(Instance!=null&&Instance!=this){Destroy(gameObject);return;}Instance=this;if(!BuildEnvironmentService.DebugUiEnabled){enabled=false;return;}DontDestroyOnLoad(gameObject);var canvas=HeroDefense.UI.UiFactory.CreateCanvas();persistentCanvas=canvas.gameObject;canvas.name="PerformanceHUDCanvas";canvas.GetComponent<Canvas>().sortingOrder=900;DontDestroyOnLoad(persistentCanvas);var panel=HeroDefense.UI.UiFactory.Panel(canvas,"PerformanceHUD",new Color(0,0,0,.7f),new Vector2(.005f,.64f),new Vector2(.2f,.995f));label=HeroDefense.UI.UiFactory.Label(panel,"Values","Performance",15,TextAnchor.UpperLeft,Color.white);HeroDefense.UI.UiFactory.Stretch(label.rectTransform,new Vector2(.04f,.04f),new Vector2(.96f,.96f));}private void Update(){if(label==null)return;elapsed+=Time.unscaledDeltaTime;frames++;if(elapsed<1)return;float fps=frames/elapsed;long memory=System.GC.GetTotalMemory(false)/(1024*1024);int allies=0,enemies=0,statuses=0;var units=Object.FindObjectsByType<CombatUnit>(FindObjectsInactive.Exclude);for(int i=0;i<units.Length;i++){if(units[i].Team==Team.Player)allies++;else enemies++;statuses+=units[i].Statuses?.Active.Count??0;}int projectiles=0;var projectilePools=Object.FindObjectsByType<ProjectilePool>(FindObjectsInactive.Exclude);for(int i=0;i<projectilePools.Length;i++)projectiles+=projectilePools[i].ActiveCount;int effects=0;var damagePools=Object.FindObjectsByType<FloatingDamageTextPool>(FindObjectsInactive.Exclude);for(int i=0;i<damagePools.Length;i++)effects+=damagePools[i].ActiveCount;label.text=$"FPS {fps:0}\nFrame {1000f/fps:0.0} ms\nAllies {allies}  Enemies {enemies}\nProjectiles {projectiles}  Effects {effects}\nStatuses {statuses}\nManaged {memory} MB";elapsed=0;frames=0;}private void OnDestroy(){if(Instance==this)Instance=null;if(persistentCanvas!=null)Destroy(persistentCanvas);}}
}
